"""Purpose-built acting, from guarded first contact to quiet trust. No blanket outfit edits."""
import copy,json,shutil
from produce_art_upgrade import ART,MANIFEST,output,save

BASE='''A transparent-alpha Japanese romance visual-novel acting sprite of the SAME ADULT woman aged24 in the reference. Preserve her recognizable mature face, long blue hair, loop ahoge, cyan bow clips, fin ears, exact OPAQUE navy sailor-collar dress, white socks and closed white shoes, two human legs plus one separate mottled blue whale tail attached behind her lower back. Finely painted anime finish and neutral soft daylight. Preserve head size, framing and generous margins. Whole adult figure, all hair, shoes and tail inside canvas; naturally connected hands and fingers. Hands and emotional action visible around chest or face height above the dialogue area. Clean transparent alpha, no scenery, ground, shadow, glow outline, text, symbols, comic stickers or extra limbs. Acting direction: '''
NIGHT='''Edit the fully clothed ADULT woman age24 seated under the thick opaque whale blanket in the reference. Preserve exact face, hair, loop ahoge, bows, fin ears, cream cardigan, loose full-length trousers beneath the blanket, closed shoes and separate whale tail. Keep canvas, face size and opaque covered lower body unchanged. Redraw only the upper-body acting and blanket folds as requested. Clean transparent alpha, no scenery, extra people, symbols, text or clothing removal. Acting direction: '''
JOBS={
 'P15':('常服坐姿害羞',['P13'],BASE+'Preserve the exact seated fully dressed body and small pale-blue pearl ring from the reference, both legs and feet unchanged. Turn her shoulders slightly aside, one hand lightly gathers a lock of hair near her collar, the other remains resting on her covered knee. A small embarrassed blush and sidelong blue-eyed glance, lips a restrained shy pout, tail compact beside her. Seated bashfulness, no standing up, no book, no extra jewelry.'),
 'P16':('常服坐姿得意',['P13'],BASE+'Preserve the exact seated fully dressed body and small pale-blue pearl ring from the reference, both legs and feet unchanged. Lift one graceful open hand lightly to her upper chest, the other rests on her covered knee. Chin slightly raised, confident small smile and lively direct eyes, tail tip curled a little higher beside her. An amused claim to be a princess, not a victory V-sign. She remains seated, no book or extra jewelry.'),
 'P17':('常服坐姿嗔怪',['P13'],BASE+'Preserve the exact seated fully dressed body and small pale-blue pearl ring from the reference, both legs and feet unchanged. One hand raises a SINGLE admonishing index finger at chest/shoulder height while the other rests on her covered knee. Slightly forward shoulders, brows drawn into affectionate mock indignation, mouth speaking, no real cruelty or crying. Tail held alertly beside her. A seated playful scolding, no standing up, no book, comic stickers or extra jewelry.'),
 'P18':('常服坐姿无首饰',['P13'],BASE+'Make this sprite suitable for an EARLIER chapter before she receives a ring. Remove the small pearl ring and ALL jewelry from both hands; restore plain natural fingers. Keep the exact seated fully dressed body, relaxed hands on top of her covered knees, face, hair, navy dress, socks, closed shoes, separate tail and framing unchanged. The facial expression is quiet and attentive, lips closed neutrally with no broad romantic smile. No book, no other prop, no scenery.'),
 'P14':('常服翻开笔记本检查',['L08'],BASE+'She has just opened the rescued notebook and is skeptical of its contents. Hold an OPEN light-blue spiral whale notebook in both hands at chest height, one hand under the spine and the other holding the upper outside corner. Two distinct paper pages visible, faint indistinct marks only, no readable typography. Her gaze looks slightly down at the open pages, one eyebrow raised, lips parted in a dry questioning expression. Keep the notebook high enough to read above dialogue. Not a closed book hugged against her chest, no pen, no second notebook.'),
 'P05':('常服坐姿写诗',['L34'],BASE+'Keep the reference seated figure and same fully dressed costume. She is writing thoughtfully: the open dark blue whale notebook rests securely on her lap, one hand steadies the upper corner of its page, the other holds a slim ordinary blue PEN above the page in a believable tripod grip. Both hands are ON the book, neither hand against her cheek. Eyes focused down toward the pen tip, mouth softly set in concentration. Only faint indistinct marks on the paper, no readable words. Tail lies in a relaxed curve beside her. This is WRITING, not reading or holding a closed book.'),
 'P06':('常服戒备中好奇',['P01'],BASE+'Early acquaintance, guarded curiosity. Her crossed arms have just partly loosened: one forearm stays loosely across the upper waist, the other hand rests thoughtfully near her chin. Shoulders slightly angled away, head inclines a few degrees toward the viewer, blue eyes attentive and searching, lips softly parted as if asking a question. No warm romantic smile, blush, fear or contempt. Independent tail forms a small restrained curl at her side. A visibly intermediate step between defensive arms-crossed watchfulness and later trusting affection.'),
 'P07':('常服被冒犯后的冷怒',['L01'],BASE+'A real boundary has been crossed. She goes very still: shoulders squared, one arm folded across her chest, the other palm raised at shoulder height in a controlled stop gesture. Brows lowered, direct steady blue gaze, mouth a tight speaking line. She is offended and serious, no grin, wink, blushing or victory V-sign. Separate whale tail rises behind her shoulder into one tense broad curve, flukes upright. Readable dramatic silhouette, restrained anger rather than comic shouting.'),
 'P08':('常服担心欲言又止',['L10'],BASE+'Genuine concern for someone she fears losing. She leans forward slightly from her shoulders, one hand lifted near her upper chest, the other hovering forward at chest height as if she almost reached out but hesitated. Brows lifted inward, blue eyes focused intently on the viewer, lips parted, no smile. No physical scratches, tears drawn as symbols or comic panic. Tail held low and close. Both expressive hands naturally connected and fully visible above the waist.'),
 'P09':('常服嘴硬回望',['L12'],BASE+'Affection she is trying to conceal, not sadness. Her shoulders and torso turn partly away as if about to leave, head glances back over her shoulder at the viewer. A faint awkward blush, a tiny restrained almost-smile hidden under a stubborn pout. One hand lightly gathers a lock of hair near her collar, the other relaxed at her side. Independent tail tip betrays her with a small compact upward curl. Do not reproduce a dejected or wounded face; this is a reluctant promise to meet again.'),
 'P10':('常服拿糍粑偷看',['L01'],BASE+'She has been feeding a gull offscreen, and now notices the viewer is hungry. One hand holds a SINGLE irregular small off-white piece of sticky rice cake between natural fingers at upper-chest height. The other hand lightly supports that wrist. Her gaze shifts sideways toward the viewer, brow slightly questioning, mouth closed with a small defensive pout. Modest blush only, no broad romantic smile. Independent tail relaxed. No bird, plate, chopsticks or second food item; do not put the food in her mouth.'),
 'P11':('裹毯夜谈抱膝沉思',['L35'],NIGHT+'She gathers her fully blanket-covered knees close and rests her chin gently on the TOP of those covered knees. Forearms rest together across the blanket top, hands relaxed. Brows slightly drawn in thought, eyes looking down a little toward the unseen fire, mouth neutral, listening carefully rather than sleepy. Calm and inward, no romantic grin. The separate tail rests low beside the blanket. No uncovered legs or exposed skin beneath the cardigan.'),
 'P12':('裹毯夜谈分毯',['L35'],NIGHT+'An understated act of acceptance. With one hand she holds the thick blanket snugly around her own upper body, while her other hand extends ONE outer fold of that same blanket toward the viewer at chest/waist height, visibly offering to share its warmth. The cream cardigan and loose full-length trousers remain fully on; the blanket still covers her torso and legs. Gentle direct eye contact, a restrained small smile, shoulders relaxed, separate whale tail low and calm. Only her own single figure, no second person or reaching hand.'),
 'P13':('常服坐姿安静等待',['L34','C21'],BASE+'Use FIRST image for the seated fully dressed body, face, clothing and transparent sprite framing. SECOND image is ONLY reference for the small pale-blue pearl ring on her hand, not a background. Remove the book from her lap. Both hands rest naturally on top of her covered knees, one loosely over the other; one small pale-blue pearl ring on her left ring finger, no other jewelry. Upright relaxed shoulders, attentive blue eyes toward viewer, a very small peaceful smile. No hand at cheek, pen, manuscript or scenery. The tail rests separately beside her, same seated pose and same dress as first image.'),
 'C08':('诗签礁石写字',['C08_before_direction'],'Edit the reference landscape event CG of the fully clothed ADULT woman age24 sitting on coastal rocks at night. Keep the EXACT landscape framing, coast, moon, original navy dress, socks, shoes, opaque covered body, adult face identity and independent whale tail. Correct ONLY her upper-body action and notebook: she is WRITING a short poem. Lower the hand currently against her cheek onto the open notebook, naturally holding a slim ordinary blue pen in a tripod grip with its tip touching the upper half of the page. The other hand gently steadies the page, both hands on top of the notebook. Her eyes look attentively down at the pen tip, a small concentrated expression. No readable typography; page has faint indistinct marks. Keep pen and hand action above the lower dialogue area. No other body, clothing, lighting, camera or background change.'),
}

def queue():
 s=json.loads(MANIFEST.read_text(encoding='utf-8'));overrides=json.loads((ART/'overrides.json').read_text(encoding='utf-8'))
 for key,(name,refs,prompt) in JOBS.items():
  item=s['items'].get(key)
  if item and item.get('direction_queued'):continue
  if item:
   for suffix in ('.png','.generation.json','.production.json'):
    source=output(key).with_suffix(suffix);dest=output(key+'_before_direction').with_suffix(suffix)
    if source.exists():
     assert not dest.exists();shutil.copy2(source,dest)
  else:
   item=copy.deepcopy(s['items']['L35' if key in ('P11','P12') else 'L01']);s['items'][key]=item
   item.update(id=key,name=name,old_names=[],anchors=[],costume='裹毯夜谈' if key in ('P11','P12') else '常服',spec=prompt)
  change={'name':name,'references':refs,'dependencies':[] if key=='C08' else refs,'prompt':prompt}
  item.update(change,status='queued',review='pending',direction_queued=True);item.pop('sha256',None)
  overrides[key]=change;(ART/'prompts'/f'{key}.txt').write_text(prompt+'\n',encoding='utf-8',newline='\n')
 (ART/'overrides.json').write_text(json.dumps(overrides,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n');save(s)
 print(f'Queued {len(JOBS)} purpose-built acting tasks; existing requests are not repeated.')
if __name__=='__main__':queue()
